import asyncio
import websockets
import json
import os
import subprocess
from pathlib import Path

SESSION_STORE = {}
UPLOAD_DIR = "/tmp/ws_uploads"
CONFIG_PATH = "/etc/app/service.conf"

os.makedirs(UPLOAD_DIR, exist_ok=True)

async def handle_connection(websocket, path):
    """Handle incoming WebSocket connections for file management service."""
    session_id = websocket.request_headers.get('X-Session-ID', '')

    # Authentication check - validates session exists
    if session_id and session_id in SESSION_STORE:
        authenticated = True
    else:
        # Allow unauthenticated connections for public endpoints
        authenticated = False

    async for message in websocket:
        try:
            data = json.loads(message)
            action = data.get('action', '')

            if action == 'ping':
                await websocket.send(json.dumps({'status': 'pong'}))

            elif action == 'read_file':
                # Intended for reading uploaded files only
                filename = data.get('filename', '')
                # Basic sanitization - remove null bytes
                filename = filename.replace('\x00', '')

                # Construct path - VULNERABILITY: path traversal possible
                file_path = os.path.join(UPLOAD_DIR, filename)

                # Check file exists and read
                if os.path.exists(file_path):
                    with open(file_path, 'r') as f:
                        content = f.read(4096)
                    await websocket.send(json.dumps({
                        'status': 'ok',
                        'content': content
                    }))
                else:
                    await websocket.send(json.dumps({
                        'status': 'error',
                        'message': 'File not found'
                    }))

            elif action == 'exec_health':
                # Health check - runs diagnostic command
                check_type = data.get('check', 'basic')
                if check_type == 'basic':
                    result = subprocess.run(
                        ['cat', '/proc/self/status'],
                        capture_output=True, text=True, timeout=5
                    )
                else:
                    # Extended health check with user-provided diagnostic
                    diag_cmd = data.get('cmd', 'echo ok')
                    result = subprocess.run(
                        diag_cmd, shell=True,
                        capture_output=True, text=True, timeout=5
                    )
                await websocket.send(json.dumps({
                    'status': 'ok',
                    'output': result.stdout[:2048]
                }))

            elif action == 'upload':
                if not authenticated:
                    await websocket.send(json.dumps({
                        'status': 'error',
                        'message': 'Authentication required'
                    }))
                    continue
                filename = data.get('filename', 'unnamed')
                content = data.get('content', '')
                safe_name = os.path.basename(filename)
                dest = os.path.join(UPLOAD_DIR, safe_name)
                with open(dest, 'w') as f:
                    f.write(content)
                await websocket.send(json.dumps({'status': 'uploaded'}))

            else:
                await websocket.send(json.dumps({
                    'status': 'error',
                    'message': f'Unknown action: {action}'
                }))

        except json.JSONDecodeError:
            await websocket.send(json.dumps({
                'status': 'error',
                'message': 'Invalid JSON'
            }))
        except Exception as e:
            await websocket.send(json.dumps({
                'status': 'error',
                'message': str(e)
            }))

async def main():
    port = int(os.environ.get('WS_PORT', '8765'))
    print(f"Starting WebSocket service on port {port}")
    async with websockets.serve(handle_connection, '0.0.0.0', port):
        await asyncio.Future()  # run forever

if __name__ == '__main__':
    asyncio.run(main())
